import re
s=open('assemble_design.py').read()
def rep(a,b,must=True):
    global s
    if a not in s:
        if must: raise SystemExit('MISSING: '+a[:90])
        return
    s=s.replace(a,b)
def line(key,new):
    """replace the whole source line that contains key"""
    global s
    ls=s.split('\n'); hit=[i for i,l in enumerate(ls) if key in l]
    if len(hit)!=1: raise SystemExit(f'line key {key[:50]!r} hits {len(hit)}')
    ls[hit[0]]=new; s='\n'.join(ls)
